/** DeviceStatus bytes14/15 are grams; tare only changes a local display offset. */
public final class ScaleActivity extends Activity {
    private RotaryController knob;private ControlClient client;private TextView value,status,target;private Button connect,tare,confirm;private boolean foreground,pendingConnect;private int selected;private final ScaleReadingTracker readings=new ScaleReadingTracker();private final Handler main=new Handler();private JSONArray ingredients=new JSONArray(),ingredientIds=new JSONArray();private LinearLayout list;private WeightArc gauge;
    private String ownerUid="",programDigest="",stepId="",checkedSession;private long checkedEpoch;private boolean checkedOwner,autoZeroPending=true,attemptedConnection;private long connectionAt;private boolean guided;private final LinkedHashMap<String,JSONObject> measured=new LinkedHashMap<>(),historical=new LinkedHashMap<>();
    private final Runnable heartbeat=new Runnable(){public void run(){if(!foreground)return;client.tick();render();main.postDelayed(this,200);}};
    @Override public void onCreate(Bundle saved){super.onCreate(saved);Ui.theme(this);knob=new RotaryController(this);client=ControlClient.get(this);
        ownerUid=getIntent().getStringExtra("ownerUid");if(ownerUid==null)ownerUid=new CloudSession(this).account().optString("uid");programDigest=getIntent().getStringExtra("programDigest");stepId=getIntent().getStringExtra("stepId");if(programDigest==null)programDigest="";if(stepId==null)stepId="";guided=!ownerUid.isEmpty()&&programDigest.matches("[a-f0-9]{64}")&&!stepId.isEmpty()&&stepId.length()<=80;
        try{String raw=getIntent().getStringExtra("ingredients");Object ids=getIntent().getExtras()==null?null:getIntent().getExtras().get("ingredientIds");if(raw!=null&&raw.length()<=65536)ingredients=new JSONArray(raw);if(ids instanceof java.util.ArrayList&&((java.util.ArrayList<?>)ids).size()<=80)ingredientIds=new JSONArray((java.util.Collection<?>)ids);else if(ids instanceof String&&((String)ids).length()<=16384)ingredientIds=new JSONArray((String)ids);if(ingredients.length()>80)ingredients=new JSONArray();}catch(JSONException ignored){ingredients=new JSONArray();}
        HashSet<String> uniqueIds=new HashSet<>();for(int i=0;i<ingredients.length();i++)if(ingredientId(i).isEmpty()||!uniqueIds.add(ingredientId(i)))guided=false;
        try{String existing=getIntent().getStringExtra("existingMeasurements");if(guided&&ownerMatches()&&existing!=null&&existing.length()<=65536){JSONObject envelope=new JSONObject(existing);if(envelope.optInt("version")==1&&ownerUid.equals(envelope.optString("ownerUid"))&&programDigest.equals(envelope.optString("programDigest"))&&stepId.equals(envelope.optString("stepId"))){JSONArray rows=RecipeWeighingHistory.forStep(envelope.getJSONArray("measurements"),new JSONObject().put("id",stepId).put("ingredients",ingredients));for(int i=0;i<rows.length();i++){JSONObject receipt=rows.getJSONObject(i);int index=receipt.getInt("ingredientIndex");if(ingredientId(index).equals(receipt.optString("ingredientId")))historical.put(receipt.getString("ingredientId"),receipt);}}}}catch(Exception ignored){historical.clear();}
        if(saved!=null&&ownerUid.equals(saved.getString("ownerUid"))&&programDigest.equals(saved.getString("programDigest"))&&stepId.equals(saved.getString("stepId"))){selected=Math.max(0,Math.min(Math.max(0,ingredients.length()-1),saved.getInt("selected",0)));try{JSONArray old=new JSONArray(saved.getString("measurements","[]"));for(int i=0;i<Math.min(old.length(),80);i++){JSONObject row=old.getJSONObject(i);int index=row.getInt("ingredientIndex");if(index>=0&&index<ingredients.length()&&ingredientId(index).equals(row.optString("ingredientId"))&&"device-scale".equals(row.optString("source")))measured.put(row.getString("ingredientId"),row);}}catch(Exception ignored){measured.clear();}}
        LinearLayout surface=Ui.column(this);surface.setBackgroundColor(Ui.BG);setContentView(surface);LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(dp(28),dp(12),dp(28),dp(8));Button back=button("‹",this::returnToRecipe);header.addView(back,new LinearLayout.LayoutParams(dp(64),dp(60)));TextView title=KitViews.text(this,guided?"Zutaten einwiegen":"Waage",29,Ui.INK,true);LinearLayout.LayoutParams titleSize=new LinearLayout.LayoutParams(0,-2,1);titleSize.leftMargin=dp(18);header.addView(title,titleSize);if(!guided){ImageButton options=new ImageButton(this);options.setImageDrawable(new InterfaceIcon("more"));options.setPadding(dp(16),dp(16),dp(16),dp(16));options.setBackground(ControlFocus.background(this,Ui.BG));options.setTag("function.options");options.setContentDescription("Optionen für Waage");options.setOnClickListener(v->FunctionVisibilityMenu.show(this,"scale","Waage",()->{}));knob.add(options);header.addView(options,new LinearLayout.LayoutParams(dp(64),dp(60)));}surface.addView(header);
        KitchenScroll scroll=new KitchenScroll(this);LinearLayout body=Ui.column(this);body.setPadding(dp(36),dp(10),dp(36),dp(24));scroll.addView(body);surface.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));String instruction=getIntent().getStringExtra("instruction");if(instruction!=null&&instruction.length()<=2400)body.addView(KitViews.text(this,instruction,22,Ui.MUTED,false));
        if(!guided){ImageView photo=new ImageView(this);photo.setTag("function.hero");photo.setBackground(KitViews.shape(this,Ui.CARD,24,0));photo.setClipToOutline(true);FunctionPhotography.bindHero(this,photo,"scale");LinearLayout.LayoutParams photoSize=new LinearLayout.LayoutParams(-1,dp(260));photoSize.bottomMargin=dp(20);body.addView(photo,photoSize);}
        target=KitViews.text(this,"",27,Ui.INK,true);target.setGravity(Gravity.CENTER);body.addView(target);value=KitViews.text(this,"— g",112,Ui.INK,true);value.setGravity(Gravity.CENTER);value.setPadding(0,dp(36),0,0);body.addView(value,new LinearLayout.LayoutParams(-1,dp(224)));status=KitViews.text(this,"",22,Ui.MUTED,false);status.setGravity(Gravity.CENTER);body.addView(status);gauge=new WeightArc();gauge.setVisibility(guided?View.VISIBLE:View.GONE);body.addView(gauge,new LinearLayout.LayoutParams(-1,dp(88)));
        
        list=Ui.column(this);body.addView(list);drawIngredients();
        if(!guided){TextView hints=KitViews.text(this,"So gelingt es",24,Ui.INK,true);hints.setPadding(0,dp(24),0,dp(10));body.addView(hints);String[] guide=ModeHelp.forMode("scale");for(int i=1;i<guide.length;i++){TextView tip=KitViews.text(this,i+". "+guide[i],19,Ui.MUTED,false);tip.setPadding(0,0,0,dp(12));body.addView(tip);}}
        LinearLayout dock=Ui.column(this);dock.setPadding(dp(36),dp(12),dp(36),dp(20));tare=button("Tara · 0 g",()->{if(readings.tare(SystemClock.elapsedRealtime()))autoZeroPending=false;render();});tare.setBackground(ControlFocus.background(this,Ui.ACCENT));tare.setTextColor(0xff171716);tare.setTag("scale.tare");dock.addView(tare,new LinearLayout.LayoutParams(-1,dp(88)));
        confirm=button("Gewicht übernehmen",this::acceptWeight);confirm.setTag("scale.confirm");LinearLayout.LayoutParams confirmSize=new LinearLayout.LayoutParams(-1,dp(64));confirmSize.topMargin=dp(8);dock.addView(confirm,confirmSize);
        Button done=button(guided?"Zurück zum Rezept":"Zurück",this::returnToRecipe);done.setTag("scale.return");LinearLayout.LayoutParams doneSize=new LinearLayout.LayoutParams(-1,dp(60));doneSize.topMargin=dp(8);dock.addView(done,doneSize);connect=button("Erneut verbinden",()->{if(!ownerMatches()||client.state.busy())return;attemptedConnection=false;autoZeroPending=true;readings.reset();connectAutomatically();render();});LinearLayout.LayoutParams connectionSize=new LinearLayout.LayoutParams(-1,dp(72));connectionSize.topMargin=dp(8);dock.addView(connect,connectionSize);surface.addView(dock);connect.setTag("scale.connect");render();
    }
    private int dp(int value){return Ui.dp(this,value);}
    private void drawIngredients(){list.removeAllViews();ArrayList<View> targets=new ArrayList<>();for(int i=0;i<ingredients.length();i++){final int index=i;JSONObject item=ingredients.optJSONObject(i);if(item==null)continue;LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(14),dp(10),dp(14),dp(10));ImageView photo=new ImageView(this);IngredientPortraits.bind(this,photo,item.optString("name"));row.addView(photo,new LinearLayout.LayoutParams(dp(68),dp(68)));JSONObject receipt=measured.get(ingredientId(i));boolean earlier=receipt==null;if(earlier)receipt=historical.get(ingredientId(i));TextView name=KitViews.text(this,item.optString("name")+(receipt==null?"":(earlier?"\nZuletzt eingewogen: ":"\nEingewogen: ")+receipt.optInt("grams")+" g"),21,Ui.INK,true);LinearLayout.LayoutParams nameSize=new LinearLayout.LayoutParams(0,-2,1);nameSize.leftMargin=dp(18);row.addView(name,nameSize);row.addView(KitViews.text(this,amount(item),21,Ui.INK,false));row.setBackground(KitViews.shape(this,selected==i?Ui.SOFT:Ui.CARD,18,selected==i?Ui.ACCENT:0));row.setContentDescription("Einwiegen: "+item.optString("name"));row.setOnClickListener(v->{if(selected!=index)readings.reset();selected=index;drawIngredients();render();});targets.add(row);LinearLayout.LayoutParams rowSize=new LinearLayout.LayoutParams(-1,-2);rowSize.topMargin=dp(10);list.addView(row,rowSize);}knob.replaceGroup("scale.ingredients",targets); }
    private String amount(JSONObject item){return !item.has("amount")||item.isNull("amount")?"Menge offen":item.optString("amount")+" "+item.optString("unit");}
    private Button button(String label,Runnable action){Button button=Ui.button(this,label,v->action.run());button.setDefaultFocusHighlightEnabled(false);button.setBackground(ControlFocus.background(this,Ui.CARD));button.setTextSize(22);button.setMinHeight(dp(64));button.setContentDescription(label);knob.add(button);return button;}
    private boolean ownerMatches(){android.content.SharedPreferences prefs=getSharedPreferences("account",0);String session=prefs.getString("session","");long epoch=prefs.getLong("epoch",0);if(!session.equals(checkedSession)||epoch!=checkedEpoch){boolean matches=ownerUid.equals(new CloudSession(this).account().optString("uid"));if(!session.equals(prefs.getString("session",""))||epoch!=prefs.getLong("epoch",0)){checkedSession=null;return false;}checkedOwner=matches;checkedSession=session;checkedEpoch=epoch;}return checkedOwner;}
    private void connectAutomatically(){if(!foreground||!ownerMatches()||attemptedConnection||client.state.connected||client.state.busy()||client.state.rootChecking||client.state.uncertainRun||client.state.deviceFaultLatched)return;attemptedConnection=true;connectionAt=SystemClock.elapsedRealtime();pendingConnect=true;if(client.state.rootVerified){pendingConnect=false;client.connect();}else client.checkRoot();}
    private String ingredientId(int index){String id=ingredientIds.optString(index,"");JSONObject item=ingredients.optJSONObject(index);if(id.isEmpty()&&item!=null)id=item.optString("ingredientId",item.optString("id",""));if(id.isEmpty())id=stepId+":ingredient-"+index;return id.length()<=180?id:"";}
    private boolean measurable(){JSONObject item=ingredients.optJSONObject(selected);return item!=null&&Arrays.asList("g","kg").contains(item.optString("unit"));}
    private Double targetGrams(){JSONObject item=ingredients.optJSONObject(selected);if(item==null||!(item.opt("amount") instanceof Number)||!measurable())return null;double amount=item.optDouble("amount",0)*(item.optString("unit").equals("kg")?1000:1);return Double.isFinite(amount)&&amount>0?amount:null;}
    private JSONArray receipts(){JSONArray result=new JSONArray();for(JSONObject row:measured.values())result.put(row);return result;}
    private void acceptWeight(){if(!guided||!ownerMatches()||!measurable())return;try{long now=SystemClock.elapsedRealtime();readings.observe(client.state,now);measured.put(ingredientId(selected),readings.confirm(ingredientId(selected),selected,targetGrams(),now,System.currentTimeMillis()));for(int n=1;n<=ingredients.length();n++){int next=(selected+n)%ingredients.length();if(!measured.containsKey(ingredientId(next))){selected=next;break;}}readings.reset();drawIngredients();render();}catch(Exception e){status.setText(e.getMessage());}}
    private void returnToRecipe(){pendingConnect=false;if(guided&&ownerMatches()&&!measured.isEmpty())try{JSONObject result=new JSONObject().put("version",1).put("ownerUid",ownerUid).put("programDigest",programDigest).put("stepId",stepId).put("measurements",receipts());setResult(RESULT_OK,new Intent().putExtra("weighingResult",result.toString()));}catch(Exception ignored){setResult(RESULT_CANCELED);}else setResult(RESULT_CANCELED);finish();}
    @Override public void onBackPressed(){returnToRecipe();}
    private void render(){if(value==null||tare==null||confirm==null)return;ControlState s=client.state;long now=SystemClock.elapsedRealtime();boolean account=ownerMatches();if(pendingConnect&&!s.rootChecking){pendingConnect=false;if(s.rootVerified&&account)client.connect();}connectAutomatically();readings.observe(s,now);if(account&&autoZeroPending&&readings.stable(now)&&readings.tare(now))autoZeroPending=false;if(!account){readings.reset();measured.clear();historical.clear();}
        boolean stable=account&&readings.stable(now);tare.setEnabled(stable);tare.setTextColor(stable?0xff171716:Ui.MUTED);boolean accept=guided&&account&&measurable()&&!ingredientId(selected).isEmpty()&&readings.canConfirm(now);confirm.setVisibility(guided?View.VISIBLE:View.GONE);confirm.setEnabled(accept);confirm.setText(accept?readings.stableGrams()+" g für diese Zutat übernehmen":"Gewicht übernehmen");confirm.setContentDescription(confirm.getText());confirm.setBackgroundTintList(android.content.res.ColorStateList.valueOf(accept?Ui.ACCENT:Ui.CARD));confirm.setTextColor(accept?0xff171716:Ui.MUTED);
        connect.setVisibility(account&&attemptedConnection&&!s.connected&&!s.busy()&&!s.rootChecking&&!pendingConnect?View.VISIBLE:View.GONE);connect.setEnabled(account&&!s.busy()&&!s.rootChecking&&!s.closing);JSONObject item=ingredients.optJSONObject(selected);target.setText(item==null?"Direkt im Mixtopf wiegen":item.optString("name")+" · "+amount(item));Double goal=targetGrams();gauge.goal=goal==null?0:goal;
        if(autoZeroPending&&readings.fresh(now)){value.setText("— g");status.setText("Waage wird auf null gesetzt …");gauge.measured=false;gauge.invalidate();return;}
        if(!readings.fresh(now)){value.setText("— g");gauge.current=0;gauge.measured=false;gauge.invalidate();status.setText(!account?"Konto gewechselt · bitte zurück zum Rezept.":s.rootChecking?"Gerätefreigabe bestätigen …":s.connecting?"Waage wird verbunden …":s.connected&&Math.abs((long)s.weightRaw)>5000?"Messbereich überschritten. Bitte die Last verringern.":s.connected?"Frische stabile Gewichtsdaten werden abgewartet …":pendingConnect||!attemptedConnection?"Waage wird verbunden …":"Waage nicht erreichbar. Bitte erneut verbinden.");return;}
        int weight=readings.displayedGrams();value.setText(weight+" g");gauge.current=weight;gauge.measured=true;gauge.invalidate();status.setText(guided&&!measurable()?"Diese Rezeptmenge ist nicht in Gramm angegeben. Im Rezept von Hand bestätigen.":autoZeroPending?"Waage wird auf null gesetzt …":!readings.hasTare()?"Zum Nullsetzen Tara wählen.":!stable?"Gewicht stabilisiert sich …":guided?(accept?"Gewicht übernehmen oder weitere Zutaten zugeben.":"Zutat hinzugeben."):"Bereit zum Wiegen");}
    @Override public boolean dispatchKeyEvent(KeyEvent event){return knob!=null&&knob.dispatch(event)||super.dispatchKeyEvent(event);}
    @Override public boolean onGenericMotionEvent(MotionEvent e){return knob!=null&&knob.motion(e)||super.onGenericMotionEvent(e);}
    @Override protected void onSaveInstanceState(Bundle state){state.putInt("selected",selected);state.putString("ownerUid",ownerUid);state.putString("programDigest",programDigest);state.putString("stepId",stepId);state.putString("measurements",receipts().toString());super.onSaveInstanceState(state);}
    @Override protected void onResume(){super.onResume();readings.reset();foreground=true;checkedSession=null;attemptedConnection=false;autoZeroPending=!guided;client.foreground(true);client.listen(this::render);connectAutomatically();main.post(heartbeat);}
    @Override protected void onPause(){foreground=false;pendingConnect=false;readings.reset();main.removeCallbacks(heartbeat);client.listen(null);client.foreground(false);super.onPause();}
    private final class WeightArc extends View{final Paint p=new Paint(3);double current,goal;boolean measured;WeightArc(){super(ScaleActivity.this);}protected void onDraw(Canvas canvas){float mid=getWidth()/2f,y=dp(68),r=Math.min(getWidth()/2f-dp(32),dp(240));p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(3));p.setStrokeCap(Paint.Cap.ROUND);p.setColor(Ui.LINE);canvas.drawArc(mid-r,y-r/5,mid+r,y+r/5,190,160,false,p);if(measured&&goal>0){p.setColor(current>goal+3?0xffffb36c:Ui.ACCENT);canvas.drawArc(mid-r,y-r/5,mid+r,y+r/5,190,160*(float)Math.max(0,Math.min(1,current/goal)),false,p);}}}
}
